export const OPENAPI_YAML: string = "openapi: 3.1.0\ninfo:\n  title: Rainbow Group Marketing API\n  version: 1.0.0\n  description: >\n    Live marketing, CRM and operations data for Rainbow International School (RIS)\n    and Rainbow Preschools (RPS). All endpoints are public — no authentication required.\n\nservers:\n  - url: https://rainbowinternationalschool.in\n\ncomponents:\n  schemas:\n    FunnelMetrics:\n      type: object\n      properties:\n        leads: { type: integer }\n        bookings: { type: integer }\n        walkins: { type: integer }\n        admissions: { type: integer }\n    LastYearMetrics:\n      type: object\n      properties:\n        spend: { type: integer }\n        leads: { type: integer }\n        walkins: { type: integer }\n        admissions: { type: integer }\n    FixedCosts:\n      type: object\n      properties:\n        salary: { type: integer }\n        crm: { type: integer }\n        overhead: { type: integer }\n\npaths:\n  /api/debug/headers:\n    get:\n      operationId: debugHeaders\n      summary: Echo request headers back (no auth required)\n      description: >\n        Returns all request headers as received by the server. Used to verify\n        which headers ChatGPT is actually sending. No authentication required.\n      responses:\n        \"200\":\n          description: Headers as seen by the server\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  method:\n                    type: string\n                    description: HTTP method of the request\n                  path:\n                    type: string\n                    description: Request path\n                  query:\n                    type: object\n                    additionalProperties:\n                      type: string\n                    description: Query string parameters\n                  headers:\n                    type: object\n                    additionalProperties:\n                      type: string\n                    description: All request headers as key-value strings\n\n  /api/marketing/export:\n    get:\n      operationId: getMarketingData\n      summary: Full marketing dashboard data for RIS and RPS\n      description: >\n        Returns monthly lead, booking, walk-in, admission and ad spend data\n        for both Rainbow International School (RIS) and Rainbow Preschools (RPS).\n        No authentication required.\n      responses:\n        \"200\":\n          description: Marketing data export\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  lastUpdated:\n                    type: string\n                  todayDate:\n                    type: integer\n                  daysInMay:\n                    type: integer\n                  minRevenuePerAdmission:\n                    type: integer\n                  monthly:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        combined:\n                          type: object\n                          properties:\n                            leads: { type: integer }\n                            bookings: { type: integer }\n                            walkins: { type: integer }\n                            admissions: { type: integer }\n                            spend: { type: integer }\n                            meta: { type: integer }\n                            google: { type: integer }\n                        ris:\n                          type: object\n                          properties:\n                            leads: { type: integer }\n                            bookings: { type: integer }\n                            walkins: { type: integer }\n                            admissions: { type: integer }\n                            spend: { type: integer }\n                            meta: { type: integer }\n                            google: { type: integer }\n                        rps:\n                          type: object\n                          properties:\n                            leads: { type: integer }\n                            bookings: { type: integer }\n                            walkins: { type: integer }\n                            admissions: { type: integer }\n                            spend: { type: integer }\n                            meta: { type: integer }\n                            google: { type: integer }\n                  organicPreSpend:\n                    type: object\n                    properties:\n                      combined: { $ref: \"#/components/schemas/FunnelMetrics\" }\n                      ris: { $ref: \"#/components/schemas/FunnelMetrics\" }\n                      rps: { $ref: \"#/components/schemas/FunnelMetrics\" }\n                  lastYear:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        ris: { $ref: \"#/components/schemas/LastYearMetrics\" }\n                        rps: { $ref: \"#/components/schemas/LastYearMetrics\" }\n                  mayWeekly:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        week: { type: string }\n                        risLeads: { type: integer }\n                        risAdm: { type: integer }\n                        risWalk: { type: integer }\n                        risBook: { type: integer }\n                        rpsLeads: { type: integer }\n                        rpsAdm: { type: integer }\n                        rpsWalk: { type: integer }\n                        rpsBook: { type: integer }\n                  social:\n                    type: object\n                    properties:\n                      ris:\n                        type: object\n                        properties:\n                          instaFollowers: { type: integer }\n                          fbFollowers: { type: integer }\n                          ytViews: { type: integer }\n                          websiteClicks: { type: integer }\n                      rps:\n                        type: object\n                        properties:\n                          instaFollowers: { type: integer }\n                          fbFollowers: { type: integer }\n                          ytViews: { type: integer }\n                          websiteClicks: { type: integer }\n                  defaultFixedCosts:\n                    type: object\n                    properties:\n                      combined: { $ref: \"#/components/schemas/FixedCosts\" }\n                      ris: { $ref: \"#/components/schemas/FixedCosts\" }\n                      rps: { $ref: \"#/components/schemas/FixedCosts\" }\n                  crmRps:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        rows:\n                          type: array\n                          items:\n                            type: object\n                            properties:\n                              centre: { type: string }\n                              leads: { type: integer }\n                              bookings: { type: integer }\n                              walkins: { type: integer }\n                              admissions: { type: integer }\n                        total:\n                          type: object\n                          properties:\n                            centre: { type: string }\n                            leads: { type: integer }\n                            bookings: { type: integer }\n                            walkins: { type: integer }\n                            admissions: { type: integer }\n        \"401\":\n          description: Missing or invalid API key.\n\n  /api/sales/live:\n    get:\n      operationId: getRisSalesLive\n      summary: RIS Sales team dashboard — walk-ins, admissions, counselor leaderboard, DM pipeline\n      description: >\n        Live RIS sales dashboard for 26-27. Returns KPIs, walk-ins by month/source/grade,\n        admissions by counselor, lead temperature, DM pipeline, month breakdown,\n        open enquiries with daysOpen, and today's RA check-ins. No auth required.\n      responses:\n        \"200\":\n          description: RIS sales dashboard data\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  kpis:\n                    type: object\n                    description: Top-level KPIs for the full academic year\n                    properties:\n                      walkinsTotal:\n                        type: integer\n                        description: Total walk-ins all time (26-27)\n                      walkinsThisMonth:\n                        type: integer\n                      admissionsTotal:\n                        type: integer\n                        description: Total confirmed admissions (from New Admission List)\n                      admissionsThisMonth:\n                        type: integer\n                      provisionalCount:\n                        type: integer\n                        description: Leads marked Provisional — not yet confirmed\n                      overallConversion:\n                        type: number\n                        description: Admission-to-walk-in conversion % (all time)\n                      openEnquiries:\n                        type: integer\n                        description: Walk-ins still active — not admitted or closed\n                      closedEnquiries:\n                        type: integer\n                      yearTarget:\n                        type: integer\n                      yearAchieved:\n                        type: integer\n                      yearTargetGap:\n                        type: integer\n                        description: yearTarget minus yearAchieved\n                  walkins:\n                    type: object\n                    properties:\n                      byMonth:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            monthKey: { type: string, description: \"YYYY-MM\" }\n                            month: { type: string }\n                            count: { type: integer }\n                      bySource:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            source: { type: string }\n                            count: { type: integer }\n                      byGrade:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            grade: { type: string }\n                            count: { type: integer }\n                      recent:\n                        type: array\n                        description: 25 most recent walk-ins\n                        items:\n                          type: object\n                          properties:\n                            date: { type: string }\n                            name: { type: string }\n                            grade: { type: string }\n                            counselor: { type: string }\n                            source: { type: string }\n                            status: { type: string }\n                  admissions:\n                    type: object\n                    properties:\n                      byMonth:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            monthKey: { type: string }\n                            month: { type: string }\n                            total: { type: integer }\n                      byBranch:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            branch: { type: string }\n                            count: { type: integer }\n                      byGrade:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            grade: { type: string }\n                            count: { type: integer }\n                      bySource:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            source: { type: string }\n                            count: { type: integer }\n                      byCounselor:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            counselor: { type: string }\n                            count: { type: integer }\n                      recent:\n                        type: array\n                        description: 25 most recent confirmed admissions\n                        items:\n                          type: object\n                          properties:\n                            date: { type: string }\n                            name: { type: string }\n                            grade: { type: string }\n                            counselor: { type: string }\n                            source: { type: string }\n                            branch: { type: string }\n                  counselorLeaderboard:\n                    type: array\n                    description: Per-counselor performance ranked by admissions\n                    items:\n                      type: object\n                      properties:\n                        counselor: { type: string }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n                        provisional: { type: integer }\n                        closed: { type: integer }\n                        followup: { type: integer }\n                        conversion:\n                          type: number\n                          description: Admission conversion % for this counselor\n                  conversionRatio:\n                    type: array\n                    description: Counselor-level enquiry-to-admission ratio\n                    items:\n                      type: object\n                      properties:\n                        counselor: { type: string }\n                        enquiries: { type: integer }\n                        open: { type: integer }\n                        closed: { type: integer }\n                        admissions: { type: integer }\n                        ratio: { type: number }\n                        provisional: { type: integer }\n                        ratioWithProv: { type: number }\n                  leadTemperature:\n                    type: object\n                    description: Count of leads by temperature bucket\n                    properties:\n                      hot: { type: integer }\n                      warm: { type: integer, description: \"FOLLOW UP status\" }\n                      cold: { type: integer, description: \"CLOSED status\" }\n                      provisional: { type: integer }\n                      open: { type: integer }\n                  monthBreakdown:\n                    type: array\n                    description: Month-by-month walkin, admission, closed and counselor detail\n                    items:\n                      type: object\n                      properties:\n                        monthKey: { type: string }\n                        label: { type: string }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n                        closed: { type: integer }\n                        provisional: { type: integer }\n                        followup: { type: integer }\n                        counselors:\n                          type: array\n                          items:\n                            type: object\n                            properties:\n                              counselor: { type: string }\n                              walkins: { type: integer }\n                              admissions: { type: integer }\n                              conversion: { type: number }\n                  dmPipeline:\n                    type: object\n                    description: Digital Marketing (DM source) pipeline from Walk-in Sheet\n                    properties:\n                      total: { type: integer }\n                      open: { type: integer }\n                      admitted: { type: integer }\n                      closed: { type: integer }\n                      provisional: { type: integer }\n                      convRate: { type: number }\n                      byRA:\n                        type: array\n                        description: Per-RA (counselor) DM pipeline breakdown\n                        items:\n                          type: object\n                          properties:\n                            ra: { type: string }\n                            total: { type: integer }\n                            open: { type: integer }\n                            admitted: { type: integer }\n                            closed: { type: integer }\n                      recentOpen:\n                        type: array\n                        description: Open DM leads sorted by age (oldest first)\n                        items:\n                          type: object\n                          properties:\n                            date: { type: string }\n                            name: { type: string }\n                            grade: { type: string }\n                            ra: { type: string }\n                            status: { type: string }\n                            daysOpen: { type: integer }\n                  openWalkins:\n                    type: array\n                    description: >\n                      All walk-in enquiries that are still open (status = OPEN or FOLLOW UP).\n                      Sorted by daysOpen descending (oldest unresolved leads first).\n                      Use this to identify stale enquiries needing follow-up.\n                    items:\n                      type: object\n                      properties:\n                        date: { type: string }\n                        name: { type: string }\n                        grade: { type: string }\n                        counselor: { type: string }\n                        source: { type: string }\n                        status: { type: string }\n                        daysOpen:\n                          type: integer\n                          description: Calendar days since the walk-in date\n                  liveCheckins:\n                    type: object\n                    description: Today's RA walk-in QR check-in data for RIS\n                    properties:\n                      todayTotal: { type: integer }\n                      byRa:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            raName: { type: string }\n                            raBranch: { type: string }\n                            count: { type: integer }\n                      last7Days:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            date: { type: string }\n                            count: { type: integer }\n\n  /api/rps-sales/live:\n    get:\n      operationId: getRpsSalesLive\n      summary: RPS Sales team dashboard — walk-ins, admissions by branch, counselor leaderboard, DM pipeline\n      description: >\n        Live RPS sales dashboard for 26-27. Returns KPIs, enquiries and admissions by\n        branch/source/grade, counselor leaderboard, closed-lead reasons, DM pipeline,\n        open walk-in enquiries with daysOpen and branch, ageing buckets, and RA check-ins.\n        No auth required.\n      responses:\n        \"200\":\n          description: RPS sales dashboard data\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  kpis:\n                    type: object\n                    description: Top-level KPIs for the full academic year\n                    properties:\n                      totalEnquiries: { type: integer }\n                      totalAdmissions: { type: integer, description: \"ADM DONE in RPS\" }\n                      totalAdmRIS: { type: integer, description: \"Leads transferred and admitted in RIS\" }\n                      openEnquiries: { type: integer }\n                      closedTotal: { type: integer }\n                      inProcess: { type: integer }\n                      futureProspect: { type: integer }\n                      overallConversion: { type: number, description: \"Admission % of total enquiries\" }\n                      thisMonthEnquiries: { type: integer }\n                      thisMonthAdm: { type: integer }\n                  byMonth:\n                    type: array\n                    description: Month-by-month enquiries and admissions\n                    items:\n                      type: object\n                      properties:\n                        monthKey: { type: string, description: \"YYYY-MM\" }\n                        label: { type: string }\n                        enquiries: { type: integer }\n                        admissions: { type: integer }\n                  byBranch:\n                    type: array\n                    description: Per-branch enquiry and admission totals with conversion rate\n                    items:\n                      type: object\n                      properties:\n                        branch: { type: string }\n                        enquiries: { type: integer }\n                        admissions: { type: integer }\n                        open: { type: integer }\n                        closed: { type: integer }\n                        conversion: { type: number, description: \"Admission % for this branch\" }\n                  bySource:\n                    type: array\n                    description: Enquiries and admissions by lead source\n                    items:\n                      type: object\n                      properties:\n                        source: { type: string }\n                        enquiries: { type: integer }\n                        admissions: { type: integer }\n                  byGrade:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        grade: { type: string }\n                        count: { type: integer }\n                  counselorLeaderboard:\n                    type: array\n                    description: Per-counselor breakdown of all lead statuses\n                    items:\n                      type: object\n                      properties:\n                        counselor: { type: string }\n                        admDone: { type: integer }\n                        admRIS: { type: integer }\n                        closed: { type: integer }\n                        open: { type: integer }\n                        inProcess: { type: integer }\n                        futureProspect: { type: integer }\n                        total: { type: integer }\n                        conversion: { type: number }\n                  closedReasons:\n                    type: array\n                    description: Top reasons why leads were closed\n                    items:\n                      type: object\n                      properties:\n                        reason: { type: string }\n                        count: { type: integer }\n                  recentEnquiries:\n                    type: array\n                    description: Most recent enquiries across all branches\n                    items:\n                      type: object\n                      properties:\n                        date: { type: string }\n                        name: { type: string }\n                        grade: { type: string }\n                        branch: { type: string }\n                        counselor: { type: string }\n                        source: { type: string }\n                        status: { type: string }\n                  openWalkins:\n                    type: array\n                    description: >\n                      Walk-in enquiries that are still open (status = OPEN, IN PROCESS, or\n                      FUTURE PROSPECT). Sorted by daysOpen descending (oldest first).\n                      Use to identify leads needing follow-up by branch or counselor.\n                    items:\n                      type: object\n                      properties:\n                        date: { type: string }\n                        name: { type: string }\n                        grade: { type: string }\n                        branch: { type: string }\n                        counselor: { type: string }\n                        source: { type: string }\n                        status: { type: string }\n                        daysOpen:\n                          type: integer\n                          description: Calendar days since the walk-in date\n                  ageingBuckets:\n                    type: object\n                    description: Open enquiry counts grouped by age bracket\n                    properties:\n                      \"0-7d\": { type: integer }\n                      \"8-14d\": { type: integer }\n                      \"15-30d\": { type: integer }\n                      \"31-60d\": { type: integer }\n                      \"60d+\": { type: integer }\n                  dmPipeline:\n                    type: object\n                    description: Digital Marketing pipeline across RPS branches\n                    properties:\n                      admitted: { type: integer }\n                      open: { type: integer }\n                      closed: { type: integer }\n                      convMedianDays: { type: integer, description: \"Median days from enquiry to admission for DM leads\" }\n                      byBranch:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            branch: { type: string }\n                            admitted: { type: integer }\n                            open: { type: integer }\n                            closed: { type: integer }\n                      byConfidence:\n                        type: array\n                        description: Open DM leads by confidence level (High, Medium, Low)\n                        items:\n                          type: object\n                          properties:\n                            confidence: { type: string }\n                            count: { type: integer }\n                      counselors:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            counselor: { type: string }\n                            open: { type: integer }\n                            admitted: { type: integer }\n                            closed: { type: integer }\n                            total: { type: integer }\n                            conv: { type: number }\n                  branchOpenPipeline:\n                    type: array\n                    description: Open pipeline counts per branch (all sources)\n                    items:\n                      type: object\n                      additionalProperties: true\n                  liveCheckins:\n                    type: object\n                    description: Today's RA walk-in QR check-in data for RPS\n                    properties:\n                      todayTotal: { type: integer }\n                      byRa:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            raName: { type: string }\n                            raBranch: { type: string }\n                            count: { type: integer }\n                      last7Days:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            date: { type: string }\n                            count: { type: integer }\n\n  /api/marketing/live:\n    get:\n      operationId: getMarketingLive\n      summary: Live combined marketing metrics from Google Sheets\n      description: >\n        Returns live monthly totals (leads, bookings, walk-ins, admissions, ad spend)\n        for both RIS and RPS combined. Also includes RPS branch-wise CRM, RIS\n        education-level CRM, closed-lead reasons, and May weekly breakdown.\n        No authentication required.\n      security: []\n      responses:\n        \"200\":\n          description: Live aggregated data\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  generatedAt: { type: string, format: date-time }\n                  currentDayOfMonth: { type: integer }\n                  monthlyTotals:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        leads: { type: integer }\n                        bookings: { type: integer }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n                        spend: { type: integer }\n                        meta: { type: integer }\n                        google: { type: integer }\n                  mayWeeklyCombined:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        week: { type: string }\n                        leads: { type: integer }\n                        bookings: { type: integer }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n                        spend: { type: integer }\n                  rpsCrm:\n                    type: object\n                    properties:\n                      byMonth:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            month: { type: string }\n                            total:\n                              type: object\n                              properties:\n                                leads: { type: integer }\n                                bookings: { type: integer }\n                                walkins: { type: integer }\n                                admissions: { type: integer }\n                                closed: { type: integer }\n                      closedReasons:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            reason: { type: string }\n                            count: { type: integer }\n                      statusSummary:\n                        type: object\n                        additionalProperties: { type: integer }\n                      bySource:\n                        type: object\n                        additionalProperties: { type: integer }\n                  risCrm:\n                    type: object\n                    properties:\n                      byMonth:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            month: { type: string }\n                            total:\n                              type: object\n                              properties:\n                                leads: { type: integer }\n                                bookings: { type: integer }\n                                walkins: { type: integer }\n                                admissions: { type: integer }\n                                closed: { type: integer }\n                      closedReasons:\n                        type: array\n                        items:\n                          type: object\n                          properties:\n                            reason: { type: string }\n                            count: { type: integer }\n                  rpsSchoolMonthly:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n                  risSchoolMonthly:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        month: { type: string }\n                        walkins: { type: integer }\n                        admissions: { type: integer }\n\n  /api/sheets/crm/rows:\n    get:\n      operationId: getSheetsCrmRows\n      summary: Raw CRM lead rows for precise date+source calculations\n      description: >\n        Raw CRM lead rows with original column headers (Enquiry Date, Source, Status,\n        Centre, Month, Lead Owner). Use for date+source counts e.g. \"Google leads on\n        20-May-26\". Includes quickCount totals (bySource, byStatus, byDate).\n        For monthly summaries use /api/sheets/crm.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [ris, rps]\n            default: rps\n          description: Which school CRM. rps = Rainbow Preschools, ris = Rainbow International School.\n        - name: date\n          in: query\n          required: false\n          schema:\n            type: string\n          description: >\n            Filter by enquiry date (partial match, case-insensitive). Examples: \"20-may-26\",\n            \"may-26\", \"20\". Leave blank for all dates.\n        - name: source\n          in: query\n          required: false\n          schema:\n            type: string\n          description: >\n            Filter by lead source (partial match). Examples: \"google\", \"meta\", \"walkin\",\n            \"instagram\", \"reference\". Leave blank for all sources.\n        - name: status\n          in: query\n          required: false\n          schema:\n            type: string\n          description: >\n            Filter by lead status. Examples: \"adm done\", \"closed\", \"walkin booked\",\n            \"walk-in completed\", \"open\". Leave blank for all statuses.\n        - name: month\n          in: query\n          required: false\n          schema:\n            type: string\n          description: Filter by month column (partial match). Example \"may\", \"apr\". Leave blank for all months.\n        - name: centre\n          in: query\n          required: false\n          schema:\n            type: string\n          description: Filter by centre or branch name (partial match). Example \"aggarwal\", \"anand nagar\". Leave blank for all centres.\n      responses:\n        \"200\":\n          description: >\n            Filtered lead rows with named columns, quickCount aggregates, and full row list.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account:\n                    type: string\n                    example: RPS\n                  filters:\n                    type: object\n                    properties:\n                      date:   { type: string }\n                      source: { type: string }\n                      status: { type: string }\n                      month:  { type: string }\n                      centre: { type: string }\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  totalRows:\n                    type: integer\n                    description: Number of rows returned after filtering.\n                  columns:\n                    type: array\n                    items: { type: string }\n                    description: >\n                      Exact column names from the sheet header row — use these as keys\n                      when reading the rows array.\n                  quickCount:\n                    type: object\n                    description: >\n                      Pre-computed aggregates over the filtered rows. Use these instead\n                      of iterating rows when you only need totals.\n                    properties:\n                      bySource:\n                        type: object\n                        additionalProperties: { type: integer }\n                        description: Lead count keyed by source value (Google, Meta, etc.).\n                      byStatus:\n                        type: object\n                        additionalProperties: { type: integer }\n                        description: Lead count keyed by status value.\n                      byDate:\n                        type: object\n                        additionalProperties: { type: integer }\n                        description: Lead count keyed by enquiry date string.\n                  rows:\n                    type: array\n                    description: >\n                      Every matching lead row as a key-value object where keys are the\n                      sheet column headers and values are cell text (always strings).\n                    items:\n                      type: object\n                      additionalProperties: { type: string }\n\n  /api/sheets/crm:\n    get:\n      operationId: getSheetsCrm\n      summary: CRM lead summary aggregated by status, source, month and owner\n      description: >\n        Returns pre-aggregated lead counts from the RPS or RIS CRM Google Sheet,\n        grouped by status (ADM DONE, CLOSED, Open, WALKIN BOOKED, WALK-IN COMPLETED),\n        lead source, month, and lead owner. Use /api/sheets/crm/rows instead when you\n        need date-level or source-level row counts.\n      parameters:\n        - name: account\n          in: query\n          required: true\n          schema:\n            type: string\n            enum: [ris, rps]\n          description: Which school CRM — ris for Rainbow International School, rps for Rainbow Preschools.\n        - name: month\n          in: query\n          required: false\n          schema:\n            type: string\n          description: Optional month filter e.g. \"may\", \"apr\". Omit for all months.\n      responses:\n        \"200\":\n          description: CRM summary with totals and breakdowns by status, source, month, and owner.\n\n  /api/sheets/master:\n    get:\n      operationId: getSheetsMaster\n      summary: Weekly funnel breakdown from the DM master tracker\n      description: Returns week-by-week lead, walk-in and admission data from the DM master Google Sheet.\n      parameters:\n        - name: account\n          in: query\n          required: true\n          schema:\n            type: string\n            enum: [ris, rps]\n          description: Which school tab to fetch.\n        - name: month\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [may, april, feb]\n          description: Month to retrieve. Defaults to may.\n      responses:\n        \"200\":\n          description: Week-by-week leads, walk-ins, admissions, conversion rates.\n\n  /api/sheets/targets:\n    get:\n      operationId: getSheetsTargets\n      summary: Branch or grade actuals vs monthly targets\n      description: >\n        RPS — per-branch actuals (leads, bookings, walk-ins, admissions) alongside monthly targets.\n        RIS — per-grade actuals (Nursery through Class 12).\n      parameters:\n        - name: account\n          in: query\n          required: true\n          schema:\n            type: string\n            enum: [ris, rps]\n          description: Which school target sheet to fetch.\n      responses:\n        \"200\":\n          description: Per-branch actuals vs targets (RPS) or per-grade actuals (RIS).\n\n  /api/sheets/tasks:\n    get:\n      operationId: getSheetsTasks\n      summary: DM team key task tracker\n      description: Returns tasks from the Key Task sheet with assignee, due date, status and remarks.\n      parameters:\n        - name: status\n          in: query\n          required: false\n          schema:\n            type: string\n          description: Filter by status e.g. \"pending\", \"completed\". Omit for all tasks.\n      responses:\n        \"200\":\n          description: Task list with summary counts (total, completed, pending).\n\n  /api/search-console/queries:\n    get:\n      operationId: getSearchConsoleQueries\n      summary: Top search queries from Google Search Console\n      description: Returns the top 25 queries by clicks for the given site over the last 28 days.\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - name: account\n          in: query\n          required: true\n          schema:\n            type: string\n            enum: [ris, rps]\n          description: Which school's Search Console property.\n      responses:\n        \"200\":\n          description: Top queries with clicks, impressions, CTR, and average position.\n        \"401\":\n          description: Missing or invalid X-Api-Key.\n\n  /api/search-console/pages:\n    get:\n      operationId: getSearchConsolePages\n      summary: Top pages from Google Search Console\n      description: Returns the top performing pages for the given site over the last 28 days.\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - name: account\n          in: query\n          required: true\n          schema:\n            type: string\n            enum: [ris, rps]\n      responses:\n        \"200\":\n          description: Top pages with clicks, impressions, CTR, and average position.\n        \"401\":\n          description: Missing or invalid X-Api-Key.\n\n  /api/pagespeed:\n    get:\n      operationId: getPageSpeedData\n      summary: PageSpeed Insights for a given URL\n      description: Returns Core Web Vitals and performance scores for a URL.\n      parameters:\n        - name: url\n          in: query\n          required: true\n          schema:\n            type: string\n          description: Full URL to test e.g. https://rainbowinternationalschool.in\n        - name: strategy\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [mobile, desktop]\n          description: Device strategy. Defaults to mobile.\n      responses:\n        \"200\":\n          description: Performance score, LCP, FID, CLS, and other Core Web Vitals.\n\n  /api/google-ads/campaigns:\n    get:\n      operationId: getGoogleAdsCampaigns\n      summary: Google Ads campaign performance (Basic Access — live data)\n      description: >\n        Live Google Ads data: spend, impressions, clicks, CTR, CPC, conversions, and\n        cost-per-conversion for all enabled campaigns (last 30 days). Use account=ris\n        for Rainbow International School or account=rps for Rainbow Preschools.\n        Basic Access tier — up to 15,000 operations/day.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [ris, rps]\n            default: ris\n          description: >\n            Which school account to query. ris = Rainbow International School,\n            rps = Rainbow Preschools. Defaults to ris.\n      responses:\n        \"200\":\n          description: Active campaigns with performance metrics for the last 30 days.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account:\n                    type: string\n                    example: RIS\n                  customerId:\n                    type: string\n                    description: Google Ads customer ID used for the query.\n                  period:\n                    type: string\n                    example: last 30 days\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  campaigns:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        id:\n                          type: string\n                          description: Google Ads campaign ID.\n                        name:\n                          type: string\n                        type:\n                          type: string\n                          description: >\n                            Advertising channel type (SEARCH, DISPLAY, VIDEO, PERFORMANCE_MAX, etc.)\n                        impressions:\n                          type: integer\n                        clicks:\n                          type: integer\n                        spend:\n                          type: number\n                          description: Total spend in INR (cost_micros / 1,000,000).\n                        conversions:\n                          type: number\n                          description: Total conversions attributed to this campaign.\n                        ctr:\n                          type: number\n                          description: Click-through rate as a percentage (e.g. 3.45 = 3.45%).\n                        avgCpc:\n                          type: number\n                          description: Average cost per click in INR.\n                        costPerConversion:\n                          type: number\n                          nullable: true\n                          description: Cost per conversion in INR. Null if no conversions.\n        \"503\":\n          description: Google Ads credentials not configured on the server.\n\n  /api/google-ads/keywords:\n    get:\n      operationId: getGoogleAdsKeywords\n      summary: Google Ads top keywords by spend (last 30 days)\n      description: >\n        Returns the top 25 active keywords by spend with clicks, impressions, CTR, avg CPC,\n        conversions, quality score, and match type. Use account=ris or account=rps to select\n        the school's Google Ads account.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [ris, rps]\n            default: ris\n          description: Which school account to query. Defaults to ris.\n      responses:\n        \"200\":\n          description: Top keywords with spend and performance data.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account:\n                    type: string\n                  customerId:\n                    type: string\n                  period:\n                    type: string\n                    example: last 30 days\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  keywords:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        keyword:\n                          type: string\n                        matchType:\n                          type: string\n                          description: EXACT, PHRASE, or BROAD.\n                        qualityScore:\n                          type: integer\n                          nullable: true\n                          description: Google Quality Score 1–10. Null if not yet assigned.\n                        impressions:\n                          type: integer\n                        clicks:\n                          type: integer\n                        spend:\n                          type: number\n                          description: Total spend in INR.\n                        conversions:\n                          type: number\n                        ctr:\n                          type: number\n                          description: Click-through rate as a percentage.\n                        avgCpc:\n                          type: number\n                          description: Average cost per click in INR.\n        \"503\":\n          description: Google Ads credentials not configured on the server.\n\n  /api/google-ads/campaign-settings:\n    get:\n      operationId: getGoogleAdsCampaignSettings\n      summary: Google Ads campaign configuration — bidding, budget, status\n      description: >\n        Campaign config for all campaigns (enabled and paused): type, bidding strategy,\n        daily budget, delivery method, start/end date. No date filter — returns all\n        campaigns regardless of spend. Use account=ris or account=rps.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema: { type: string, enum: [ris, rps], default: ris }\n      responses:\n        \"200\":\n          description: Campaign config including budget and bidding strategy.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account: { type: string }\n                  customerId: { type: string }\n                  generatedAt: { type: string, format: date-time }\n                  campaigns:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        id: { type: string }\n                        name: { type: string }\n                        status: { type: string }\n                        type: { type: string }\n                        biddingStrategy: { type: string }\n                        startDate: { type: string, nullable: true }\n                        endDate: { type: string, nullable: true }\n                        dailyBudget: { type: number, nullable: true }\n                        deliveryMethod: { type: string, nullable: true }\n\n  /api/google-ads/ad-groups:\n    get:\n      operationId: getGoogleAdsAdGroups\n      summary: Google Ads ad group performance for current month\n      description: >\n        Ad group spend, clicks, impressions, CTR, CPC, and conversions for the current\n        calendar month. Shows all ad groups with spend > 0. Useful for seeing whether\n        setup is branch-wise, theme-wise, or generic. Use account=ris or account=rps.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema: { type: string, enum: [ris, rps], default: ris }\n      responses:\n        \"200\":\n          description: Ad groups with performance metrics for current month.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account: { type: string }\n                  customerId: { type: string }\n                  period: { type: string }\n                  generatedAt: { type: string, format: date-time }\n                  adGroups:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        campaignId: { type: string }\n                        campaignName: { type: string }\n                        campaignStatus: { type: string }\n                        adGroupId: { type: string }\n                        adGroupName: { type: string }\n                        adGroupStatus: { type: string }\n                        type: { type: string }\n                        impressions: { type: integer }\n                        clicks: { type: integer }\n                        spend: { type: number }\n                        conversions: { type: number }\n                        ctr: { type: number }\n                        avgCpc: { type: number }\n\n  /api/google-ads/ads:\n    get:\n      operationId: getGoogleAdsAds\n      summary: Google Ads ad copy, landing pages, and performance\n      description: >\n        Ad-level data for current month: ad type, final landing page URLs, RSA\n        headlines and descriptions, plus impressions, clicks, spend, conversions,\n        and CTR. Shows all ads with spend > 0. Use account=ris or account=rps.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema: { type: string, enum: [ris, rps], default: ris }\n      responses:\n        \"200\":\n          description: Ads with copy, landing pages, and performance for current month.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account: { type: string }\n                  customerId: { type: string }\n                  period: { type: string }\n                  generatedAt: { type: string, format: date-time }\n                  ads:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        campaignId: { type: string }\n                        campaignName: { type: string }\n                        adGroupId: { type: string }\n                        adGroupName: { type: string }\n                        adId: { type: string }\n                        adStatus: { type: string }\n                        adType: { type: string }\n                        finalUrls:\n                          type: array\n                          items: { type: string }\n                        headlines:\n                          type: array\n                          items: { type: string }\n                        descriptions:\n                          type: array\n                          items: { type: string }\n                        impressions: { type: integer }\n                        clicks: { type: integer }\n                        spend: { type: number }\n                        conversions: { type: number }\n                        ctr: { type: number }\n\n  /api/google-ads/locations:\n    get:\n      operationId: getGoogleAdsLocations\n      summary: Google Ads geographic targeting (location and proximity criteria)\n      description: >\n        Returns all LOCATION and PROXIMITY campaign criteria — the geographic areas\n        each campaign is targeting or excluding. Includes geo_target_constant for\n        city lookups and proximity radius/coordinates. Use account=ris or account=rps.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema: { type: string, enum: [ris, rps], default: ris }\n      responses:\n        \"200\":\n          description: Location and proximity targeting criteria per campaign.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account: { type: string }\n                  customerId: { type: string }\n                  generatedAt: { type: string, format: date-time }\n                  locations:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        campaignId: { type: string }\n                        campaignName: { type: string }\n                        criterionId: { type: string }\n                        type: { type: string, description: LOCATION or PROXIMITY }\n                        isNegative: { type: boolean }\n                        geoTargetConstant: { type: string, nullable: true }\n                        proximity:\n                          type: object\n                          nullable: true\n                          properties:\n                            radius: { type: number }\n                            radiusUnits: { type: string }\n                            cityName: { type: string, nullable: true }\n                            latMicro: { type: integer, nullable: true }\n                            lngMicro: { type: integer, nullable: true }\n\n  /api/google-ads/conversion-actions:\n    get:\n      operationId: getGoogleAdsConversionActions\n      summary: Google Ads conversion actions setup and tracking configuration\n      description: >\n        Lists all conversion actions configured in the account: name, status, type,\n        category (form submit, call, WhatsApp click, etc.), origin, counting type,\n        and whether included in the campaign's conversions metric.\n        Use account=ris or account=rps.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema: { type: string, enum: [ris, rps], default: ris }\n      responses:\n        \"200\":\n          description: All conversion actions with tracking setup details.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account: { type: string }\n                  customerId: { type: string }\n                  generatedAt: { type: string, format: date-time }\n                  conversionActions:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        id: { type: string }\n                        name: { type: string }\n                        status: { type: string }\n                        type: { type: string }\n                        category: { type: string }\n                        origin: { type: string }\n                        countingType: { type: string }\n                        includeInConversionsMetric: { type: boolean }\n\n  /api/meta-ads/campaigns:\n    get:\n      operationId: getMetaAdsCampaigns\n      summary: Meta (Facebook/Instagram) Ads campaign performance (last 30 days)\n      description: >\n        Returns spend, reach, impressions, clicks, CTR, CPC, leads, landing page views,\n        and cost-per-lead for all active Meta campaigns. Use account=ris to filter to\n        Rainbow International School campaigns, account=rps for Rainbow Preschools,\n        or omit (all) to get every campaign across both brands.\n      parameters:\n        - name: account\n          in: query\n          required: false\n          schema:\n            type: string\n            enum: [ris, rps, all]\n            default: all\n          description: >\n            Filter campaigns by brand name. ris = school campaigns, rps = preschool\n            campaigns, all = every campaign on the account.\n      responses:\n        \"200\":\n          description: Meta campaign performance data for the last 30 days.\n          content:\n            application/json:\n              schema:\n                type: object\n                properties:\n                  account:\n                    type: string\n                  period:\n                    type: string\n                    example: last_30d\n                  generatedAt:\n                    type: string\n                    format: date-time\n                  total:\n                    type: object\n                    properties:\n                      campaigns:\n                        type: integer\n                      spend:\n                        type: number\n                      impressions:\n                        type: integer\n                      clicks:\n                        type: integer\n                      leads:\n                        type: integer\n                  campaigns:\n                    type: array\n                    items:\n                      type: object\n                      properties:\n                        id:\n                          type: string\n                        name:\n                          type: string\n                        status:\n                          type: string\n                          description: ACTIVE, PAUSED, etc.\n                        objective:\n                          type: string\n                          description: LEAD_GENERATION, LINK_CLICKS, etc.\n                        impressions:\n                          type: integer\n                        clicks:\n                          type: integer\n                        spend:\n                          type: number\n                          description: Spend in INR.\n                        reach:\n                          type: integer\n                        frequency:\n                          type: number\n                          description: Average number of times each person saw the ad.\n                        ctr:\n                          type: number\n                          description: Click-through rate as a percentage.\n                        cpc:\n                          type: number\n                          description: Cost per click in INR.\n                        leads:\n                          type: integer\n                          description: Form submissions / lead actions.\n                        landingPageViews:\n                          type: integer\n                        costPerLead:\n                          type: number\n                          nullable: true\n                          description: Cost per lead in INR. Null if no leads.\n        \"503\":\n          description: Meta Ads token or account ID not configured on the server.\n";
